-- REVIEW ONLY. Depends on owner-role-bounds.review-only.sql. Never catalogued or applied to hosted data.
-- Existing base roles, grants, task rows and memberships remain unchanged on installation.
CREATE TABLE ab.staff_appointments(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,person_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('role','delegation')),company_id uuid NOT NULL,department_id uuid,template_version_id uuid,source_employee_id uuid,substitute_employee_id uuid,starts_at timestamptz NOT NULL,ends_at timestamptz,ended_at timestamptz,reason_cipher text NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at IS NULL OR ends_at>starts_at),CHECK(kind='role'OR ends_at IS NOT NULL),FOREIGN KEY(tenant_id,person_id)REFERENCES ab.users(tenant_id,id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,department_id)REFERENCES ab.departments(tenant_id,id),FOREIGN KEY(template_version_id)REFERENCES ab.permission_template_versions(id),FOREIGN KEY(tenant_id,source_employee_id)REFERENCES ab.hr_employees(tenant_id,id),FOREIGN KEY(tenant_id,substitute_employee_id)REFERENCES ab.hr_employees(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id),UNIQUE(tenant_id,id));
CREATE TABLE ab.staff_appointment_grants(appointment_id uuid NOT NULL REFERENCES ab.staff_appointments(id),grant_id uuid NOT NULL REFERENCES ab.permission_grants(id)DEFERRABLE INITIALLY DEFERRED,tenant_id uuid NOT NULL,managed boolean NOT NULL,source_grant_id uuid REFERENCES ab.permission_grants(id),PRIMARY KEY(appointment_id,grant_id));
CREATE TABLE ab.staff_appointment_tasks(appointment_id uuid NOT NULL REFERENCES ab.staff_appointments(id),task_id uuid NOT NULL REFERENCES ab.tasks(id),tenant_id uuid NOT NULL,original_employee_id uuid NOT NULL,PRIMARY KEY(appointment_id,task_id));
CREATE TABLE ab.staff_appointment_events(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,appointment_id uuid NOT NULL REFERENCES ab.staff_appointments(id),actor_id uuid NOT NULL,authority text NOT NULL CHECK(authority IN('owner','scheduler')),action text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(appointment_id,action));
CREATE TRIGGER immutable_staff_appointment_events BEFORE UPDATE OR DELETE ON ab.staff_appointment_events FOR EACH ROW EXECUTE FUNCTION ab.vehicle_immutable();
CREATE INDEX staff_appointments_person ON ab.staff_appointments(tenant_id,person_id,company_id);
CREATE FUNCTION ab.staff_appointments_version()RETURNS text LANGUAGE sql IMMUTABLE AS $$SELECT 'AB-STAFF-APPOINTMENTS-REVIEW-1'::text$$;
CREATE FUNCTION ab.staff_appointment_active(key uuid)RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,ab AS $$SELECT EXISTS(SELECT 1 FROM ab.staff_appointments a JOIN ab.users u ON u.id=a.person_id AND u.tenant_id=a.tenant_id WHERE a.id=key AND a.tenant_id=ab.tenant()AND u.status='Active'AND u.role_id<>'owner'AND(a.kind='role'OR EXISTS(SELECT 1 FROM ab.hr_employees e WHERE e.id=a.source_employee_id AND e.state<>'Ended'))AND a.ended_at IS NULL AND a.starts_at<=now()AND(a.ends_at IS NULL OR a.ends_at>now())AND EXISTS(SELECT 1 FROM ab.user_companies co WHERE co.user_id=a.person_id AND co.company_id=a.company_id AND co.active)AND(a.department_id IS NULL OR EXISTS(SELECT 1 FROM ab.user_departments d WHERE d.user_id=a.person_id AND d.department_id=a.department_id AND d.active)))$$;
CREATE FUNCTION ab.staff_grant_active(key uuid)RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,ab AS $$DECLARE link record; source_revoked timestamptz;BEGIN
 IF NOT EXISTS(SELECT 1 FROM ab.staff_appointment_grants l WHERE l.grant_id=key AND l.tenant_id=ab.tenant()AND l.managed)THEN RETURN true;END IF;
 FOR link IN SELECT l.* FROM ab.staff_appointment_grants l WHERE l.grant_id=key AND l.tenant_id=ab.tenant()LOOP
  IF NOT ab.staff_appointment_active(link.appointment_id)THEN CONTINUE;END IF;
  IF link.source_grant_id IS NULL THEN RETURN true;END IF;
  SELECT revoked_at INTO source_revoked FROM ab.permission_grants WHERE id=link.source_grant_id;
  IF FOUND AND source_revoked IS NULL AND(NOT EXISTS(SELECT 1 FROM ab.staff_appointment_grants l WHERE l.grant_id=link.source_grant_id AND l.managed)OR EXISTS(SELECT 1 FROM ab.staff_appointment_grants l JOIN ab.staff_appointments a ON a.id=l.appointment_id WHERE l.grant_id=link.source_grant_id AND a.kind='role'AND ab.staff_appointment_active(a.id)))THEN RETURN true;END IF;
 END LOOP;RETURN false;
END$$;
CREATE POLICY staff_grant_clock ON ab.permission_grants AS RESTRICTIVE USING(ab.staff_grant_active(id))WITH CHECK(true);
CREATE FUNCTION ab.staff_task_assignee(key uuid,original uuid)RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,ab AS $$SELECT coalesce((SELECT a.substitute_employee_id FROM ab.staff_appointment_tasks l JOIN ab.staff_appointments a ON a.id=l.appointment_id WHERE l.task_id=key AND l.original_employee_id=original AND l.tenant_id=ab.tenant()AND ab.staff_appointment_active(a.id)ORDER BY a.starts_at,a.id LIMIT 1),original)$$;
CREATE FUNCTION ab.staff_appointment_validate()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ab AS $$DECLARE a ab.staff_appointments;g ab.permission_grants;src ab.permission_grants;v ab.permission_template_versions;t ab.tasks;BEGIN
 IF NOT ab.access_owner()THEN RAISE EXCEPTION 'owner required' USING ERRCODE='42501';END IF;
 IF TG_TABLE_NAME='staff_appointments'THEN
 IF TG_OP='UPDATE'THEN IF OLD.ended_at IS NOT NULL OR NEW.ended_at IS NULL OR (to_jsonb(NEW)-'ended_at')IS DISTINCT FROM(to_jsonb(OLD)-'ended_at')THEN RAISE EXCEPTION 'immutable appointment' USING ERRCODE='42501';END IF;RETURN NEW;END IF;
 IF NEW.tenant_id<>ab.tenant()OR NEW.created_by<>nullif(current_setting('ab.actor',true),'')::uuid OR NEW.person_id=NEW.created_by OR NOT EXISTS(SELECT 1 FROM ab.users u JOIN ab.user_companies co ON co.user_id=u.id WHERE u.id=NEW.person_id AND u.tenant_id=NEW.tenant_id AND u.status='Active'AND u.role_id<>'owner'AND co.company_id=NEW.company_id AND co.active)THEN RAISE EXCEPTION 'appointment user company' USING ERRCODE='23514';END IF;
 IF NEW.department_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM ab.departments d JOIN ab.user_departments u ON u.department_id=d.id WHERE d.id=NEW.department_id AND d.company_id=NEW.company_id AND u.user_id=NEW.person_id AND u.active)THEN RAISE EXCEPTION 'appointment unit' USING ERRCODE='23514';END IF;
 IF NEW.kind='role'THEN SELECT * INTO v FROM ab.permission_template_versions WHERE id=NEW.template_version_id;IF v.tenant_id IS DISTINCT FROM NEW.tenant_id OR v.kind<>'role'OR v.target_id='owner'OR NEW.source_employee_id IS NOT NULL OR NEW.substitute_employee_id IS NOT NULL THEN RAISE EXCEPTION 'role template required' USING ERRCODE='23514';END IF;
 ELSE IF NEW.template_version_id IS NOT NULL OR NEW.source_employee_id IS NULL OR NEW.substitute_employee_id IS NULL OR NEW.source_employee_id=NEW.substitute_employee_id OR NOT EXISTS(SELECT 1 FROM ab.hr_employees e WHERE e.id=NEW.substitute_employee_id AND e.company_id=NEW.company_id AND e.user_id=NEW.person_id)OR NOT EXISTS(SELECT 1 FROM ab.hr_employees e WHERE e.id=NEW.source_employee_id AND e.company_id=NEW.company_id AND e.user_id IS NOT NULL)THEN RAISE EXCEPTION 'delegation employees' USING ERRCODE='23514';END IF;END IF;RETURN NEW;
 ELSIF TG_TABLE_NAME='staff_appointment_grants'THEN
 SELECT * INTO a FROM ab.staff_appointments WHERE id=NEW.appointment_id;SELECT * INTO g FROM ab.permission_grants WHERE id=NEW.grant_id;
 IF a.tenant_id IS DISTINCT FROM NEW.tenant_id OR g.tenant_id IS DISTINCT FROM NEW.tenant_id OR g.user_id IS DISTINCT FROM a.person_id OR g.scope_type<>'company'OR g.company_id IS DISTINCT FROM a.company_id OR g.delegable THEN RAISE EXCEPTION 'appointment grant company' USING ERRCODE='23514';END IF;
 IF a.kind='role'AND(NEW.source_grant_id IS NOT NULL OR g.permission_id~'(_approve$|_decision$|grant|reset|redelegate|_disburse$|_pay$|_settlement$|_writeoff$)')THEN RAISE EXCEPTION 'role source must be template' USING ERRCODE='23514';END IF;IF a.kind='delegation'THEN SELECT * INTO src FROM ab.permission_grants WHERE id=NEW.source_grant_id;IF src.id IS NULL OR src.tenant_id<>a.tenant_id OR src.permission_id<>g.permission_id OR src.scope_type<>g.scope_type OR src.company_id IS DISTINCT FROM g.company_id OR src.revoked_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM ab.hr_employees e WHERE e.id=a.source_employee_id AND e.user_id=src.user_id)OR g.permission_id~'(approve|decision|grant|reset|redelegate|funding|disburse|settlement|writeoff|payroll)'OR EXISTS(SELECT 1 FROM ab.staff_appointment_grants l JOIN ab.staff_appointments x ON x.id=l.appointment_id WHERE l.grant_id=src.id AND x.kind='delegation')THEN RAISE EXCEPTION 'non transferable authority' USING ERRCODE='23514';END IF;END IF;RETURN NEW;
 ELSIF TG_TABLE_NAME='staff_appointment_tasks'THEN SELECT * INTO a FROM ab.staff_appointments WHERE id=NEW.appointment_id;SELECT * INTO t FROM ab.tasks WHERE id=NEW.task_id;PERFORM pg_advisory_xact_lock(hashtext('staff-task:'||NEW.task_id::text));IF a.tenant_id IS DISTINCT FROM NEW.tenant_id OR t.tenant_id IS DISTINCT FROM a.tenant_id OR t.company_id IS DISTINCT FROM a.company_id OR a.kind<>'delegation'OR t.employee_id IS DISTINCT FROM a.source_employee_id OR NEW.original_employee_id IS DISTINCT FROM t.employee_id OR t.state IN('Completed','Closed')OR EXISTS(SELECT 1 FROM ab.staff_appointment_tasks l JOIN ab.staff_appointments x ON x.id=l.appointment_id WHERE l.task_id=NEW.task_id AND x.id<>a.id AND x.ended_at IS NULL AND x.starts_at<a.ends_at AND(x.ends_at IS NULL OR x.ends_at>a.starts_at))THEN RAISE EXCEPTION 'task delegation conflict' USING ERRCODE='23514';END IF;RETURN NEW;
 END IF;RETURN NEW;END$$;
CREATE TRIGGER staff_appointment_validate BEFORE INSERT OR UPDATE ON ab.staff_appointments FOR EACH ROW EXECUTE FUNCTION ab.staff_appointment_validate();
CREATE CONSTRAINT TRIGGER staff_appointment_grant_validate AFTER INSERT ON ab.staff_appointment_grants DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ab.staff_appointment_validate();
CREATE TRIGGER staff_appointment_task_validate BEFORE INSERT ON ab.staff_appointment_tasks FOR EACH ROW EXECUTE FUNCTION ab.staff_appointment_validate();
CREATE FUNCTION ab.staff_grant_revoke_guard()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ab AS $$BEGIN IF NEW.revoked_at IS DISTINCT FROM OLD.revoked_at AND EXISTS(SELECT 1 FROM ab.staff_appointment_grants l JOIN ab.staff_appointments a ON a.id=l.appointment_id WHERE l.grant_id=OLD.id AND a.tenant_id=ab.tenant()AND a.ended_at IS NULL AND(a.ends_at IS NULL OR a.ends_at>now()))AND NOT EXISTS(SELECT 1 FROM ab.permission_template_exceptions e WHERE e.grant_id=OLD.id AND e.tenant_id=OLD.tenant_id)THEN RAISE EXCEPTION 'end assignment or approved exception first' USING ERRCODE='42501';END IF;RETURN NEW;END$$;
CREATE TRIGGER staff_appointment_grant_guard BEFORE UPDATE ON ab.permission_grants FOR EACH ROW EXECUTE FUNCTION ab.staff_grant_revoke_guard();
DO $$DECLARE tab text;BEGIN FOREACH tab IN ARRAY ARRAY['staff_appointments','staff_appointment_grants','staff_appointment_tasks','staff_appointment_events']LOOP
 EXECUTE format('ALTER TABLE ab.%I ENABLE ROW LEVEL SECURITY',tab);
 EXECUTE format('CREATE POLICY staff_read ON ab.%I FOR SELECT USING(tenant_id=ab.tenant()AND(ab.access_owner()OR EXISTS(SELECT 1 FROM ab.staff_appointments a WHERE a.id=%s AND a.person_id=nullif(current_setting(''ab.actor'',true),'''')::uuid)))',tab,CASE WHEN tab='staff_appointments'THEN 'id'ELSE 'appointment_id'END);
 EXECUTE format('CREATE POLICY staff_owner_insert ON ab.%I FOR INSERT WITH CHECK(tenant_id=ab.tenant()AND ab.access_owner())',tab);
 EXECUTE format('GRANT SELECT,INSERT ON ab.%I TO ab_runtime',tab);
END LOOP;END$$;
-- Avoid recursion in the appointments table's own read policy.
DROP POLICY staff_read ON ab.staff_appointments;
CREATE POLICY staff_read ON ab.staff_appointments FOR SELECT USING(tenant_id=ab.tenant()AND(ab.access_owner()OR person_id=nullif(current_setting('ab.actor',true),'')::uuid));
CREATE POLICY staff_owner_end ON ab.staff_appointments FOR UPDATE USING(tenant_id=ab.tenant()AND ab.access_owner())WITH CHECK(tenant_id=ab.tenant()AND ab.access_owner());GRANT UPDATE(ended_at)ON ab.staff_appointments TO ab_runtime;
REVOKE ALL ON FUNCTION ab.staff_appointment_validate(),ab.staff_grant_revoke_guard()FROM PUBLIC;
REVOKE ALL ON FUNCTION ab.staff_appointment_active(uuid),ab.staff_grant_active(uuid),ab.staff_task_assignee(uuid,uuid),ab.staff_appointments_version()FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ab.staff_appointment_active(uuid),ab.staff_grant_active(uuid),ab.staff_task_assignee(uuid,uuid),ab.staff_appointments_version()TO ab_runtime;
